#!/usr/bin/env bash
# Generates and configures the ios/ project (idempotent). Run from the repo root on macOS:
#
#   bash tool/ios_setup.sh
#
# The ios/ directory is generated by `flutter create` instead of being committed, then
# patched here for everything Boorusphere needs on iOS:
#   - AppDelegate: flutter_downloader plugin registrant callback
#   - Info.plist: downloads visible in the Files app, background downloads,
#     cleartext HTTP for boorus without TLS, app name
#   - Podfile / Xcode: iOS 14 deployment target (file_picker 12+; media_kit needs 13)
#   - app icon generated from assets/icons/ios-icon.png (Android icon colors, larger logo)
set -euo pipefail

if [ "$(uname)" != "Darwin" ]; then
  echo "tool/ios_setup.sh needs macOS (PlistBuddy)." >&2
  exit 1
fi

if [ ! -f pubspec.yaml ]; then
  echo "Run this from the repository root." >&2
  exit 1
fi

ORG="io.chaldeaprjkt"
PROJECT="boorusphere"
DISPLAY_NAME="Boorusphere"

# 1. Generate the iOS runner if needed
if [ ! -d ios ]; then
  flutter create --platforms=ios --org "$ORG" --project-name "$PROJECT" .
fi

# Same versions as the Android and test jobs: fail if pubspec.lock is stale.
flutter pub get --enforce-lockfile

# 2. App icon
# The config file must NOT be named flutter_launcher_icons-<x>.yaml: the tool
# treats <x> as a flavor and writes AppIcon-<x>.appiconset, which the app never
# uses (it keeps the default Flutter icon).
cat > ios_launcher_icons.yaml <<EOF
flutter_launcher_icons:
  ios: true
  android: false
  image_path: "assets/icons/ios-icon.png"
  remove_alpha_ios: true
EOF
dart run flutter_launcher_icons -f ios_launcher_icons.yaml
rm -f ios_launcher_icons.yaml
if ls -d ios/Runner/Assets.xcassets/AppIcon-*.appiconset >/dev/null 2>&1; then
  echo "ERROR: icons were generated as a flavor icon set" >&2
  exit 1
fi

# 3. AppDelegate (flutter_downloader needs to register its plugins for background isolates)
# Since Flutter 3.38 `flutter create` generates the UIScene lifecycle (SceneDelegate,
# FlutterImplicitEngineDelegate). The app keeps the classic AppDelegate lifecycle for
# now (the UIApplicationSceneManifest is removed from Info.plist in step 4), so the
# plugins keep the window/app-delegate callbacks they were tested with. The generated
# SceneDelegate.swift stays in the project but is not used.
cat > ios/Runner/AppDelegate.swift <<'EOF'
import Flutter
import UIKit
import flutter_downloader

@main
@objc class AppDelegate: FlutterAppDelegate {
  override func application(
    _ application: UIApplication,
    didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?
  ) -> Bool {
    GeneratedPluginRegistrant.register(with: self)
    FlutterDownloaderPlugin.setPluginRegistrantCallback(registerPlugins)
    return super.application(application, didFinishLaunchingWithOptions: launchOptions)
  }
}

private func registerPlugins(registry: FlutterPluginRegistry) {
  if !registry.hasPlugin("FlutterDownloaderPlugin") {
    FlutterDownloaderPlugin.register(
      with: registry.registrar(forPlugin: "FlutterDownloaderPlugin")!)
  }
}
EOF

# 4. Info.plist
PLIST=ios/Runner/Info.plist
PB=/usr/libexec/PlistBuddy

set_or_add() { # key type value
  "$PB" -c "Set :$1 $3" "$PLIST" 2>/dev/null || "$PB" -c "Add :$1 $2 $3" "$PLIST"
}

set_or_add CFBundleDisplayName string "$DISPLAY_NAME"
# Classic AppDelegate lifecycle, see step 3
"$PB" -c "Delete :UIApplicationSceneManifest" "$PLIST" 2>/dev/null || true
# Downloads/backups live in Documents/Boorusphere and should show up in the Files app
set_or_add UIFileSharingEnabled bool true
set_or_add LSSupportsOpeningDocumentsInPlace bool true
# monloader on the home network (Send to Monbooru)
plutil -replace NSPhotoLibraryAddUsageDescription -string "Used to save downloaded images and videos to Photos." "$PLIST"
plutil -replace NSPhotoLibraryUsageDescription -string "Used to save downloaded images and videos to Photos." "$PLIST"
plutil -replace NSLocalNetworkUsageDescription -string "Used to reach your monloader server on the local network." "$PLIST"
# flutter_downloader settings
set_or_add FDMaximumConcurrentTasks integer 3
set_or_add FDAllowsCellularAccess bool true
# Plain HTTP stays allowed for all hosts on purpose (intentional trade-off, see #5
# and DEVELOPMENT.md "Security notes"): user-added boorus without HTTPS must keep
# working, and AVPlayer/NSURLSession (downloads) enforce ATS. All bundled servers
# use HTTPS; tokens get a warning in the UI when they would go over plain HTTP.
"$PB" -c "Delete :NSAppTransportSecurity" "$PLIST" 2>/dev/null || true
"$PB" -c "Add :NSAppTransportSecurity dict" "$PLIST"
"$PB" -c "Add :NSAppTransportSecurity:NSAllowsArbitraryLoads bool true" "$PLIST"
# flutter_downloader background modes
"$PB" -c "Delete :UIBackgroundModes" "$PLIST" 2>/dev/null || true
"$PB" -c "Add :UIBackgroundModes array" "$PLIST"
"$PB" -c "Add :UIBackgroundModes:0 string fetch" "$PLIST"
"$PB" -c "Add :UIBackgroundModes:1 string remote-notification" "$PLIST"

# 5. iOS 14 deployment target (file_picker 12+ requires 14, media_kit 13)
python3 - <<'EOF'
import pathlib, re
p = pathlib.Path("ios/Podfile")
s = p.read_text()
if not re.search(r"^platform :ios", s, re.M):
    s, n = re.subn(r"^#\s*platform :ios, '[0-9.]+'", "platform :ios, '14.0'", s, count=1, flags=re.M)
    if n == 0:
        s = "platform :ios, '14.0'\n" + s
else:
    s = re.sub(r"^platform :ios, '[0-9.]+'", "platform :ios, '14.0'", s, count=1, flags=re.M)
p.write_text(s)
EOF
sed -i.bak "s/IPHONEOS_DEPLOYMENT_TARGET = [0-9.]*;/IPHONEOS_DEPLOYMENT_TARGET = 14.0;/g" \
  ios/Runner.xcodeproj/project.pbxproj
rm -f ios/Runner.xcodeproj/project.pbxproj.bak

echo "iOS project ready."
